const express = require('express');
const app = express();
const port = 9999;

app.get('/', (req, res) => {
  res.send('Hello from Express!');
});


app.get('/sr', (req, res) => {
  res.send('hi this is srinidhi!');
});

app.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});
